import urllib.request, urllib.parse, json, ssl
base='https://geo.salvador.ba.gov.br/portal/sharing/rest/search'; ctx=ssl.create_default_context(); headers={'User-Agent':'Mozilla/5.0 ChatGPTTerrainResearch/1.0'}
queries=['curva de nivel','curvas de nivel','curva nível','altimetria','altimetrico','altimétrico','cota','pontos cotados','topografia','topografico','levantamento topografico','SICAD','cartografia 2017','relevo','terreno owner:GEO_FMLF','owner:GEO_FMLF type:"Feature Service"','owner:GEO_FMLF type:"Map Service"','owner:GEO_FMLF type:"Image Service"']
seen={}
for q in queries:
    try:
        url=base+'?'+urllib.parse.urlencode({'f':'json','q':q,'num':100,'start':1})
        req=urllib.request.Request(url,headers=headers)
        with urllib.request.urlopen(req,timeout=30,context=ctx) as r: d=json.loads(r.read().decode('utf-8'))
        print('QUERY',q,'TOTAL',d.get('total'),'RETURNED',len(d.get('results',[])))
        for it in d.get('results',[]):
            if str(it.get('owner','')).lower().startswith('esri_'): continue
            seen[it.get('id')]=it
    except Exception as e: print('ERR',q,type(e).__name__,str(e))
print('MUNICIPAL_ITEMS='+str(len(seen)))
for it in sorted(seen.values(),key=lambda x:str(x.get('title','')).lower()):
    print(json.dumps({'id':it.get('id'),'title':it.get('title'),'type':it.get('type'),'owner':it.get('owner'),'url':it.get('url'),'tags':it.get('tags'),'access':it.get('access')},ensure_ascii=False))
print('ALTIMETRY_SEARCH_DONE')
